import math
from sympy import factorint
def h(D):
    cnt = 0; a = 1
    while 3*a*a <= -D:
        for b in range(-a+1, a+1):
            if (b*b - D) % (4*a) == 0:
                c = (b*b - D)//(4*a)
                if c < a or (c == a and b < 0): continue
                if math.gcd(math.gcd(a, abs(b)), c) != 1: continue
                cnt += 1
        a += 1
    return cnt
def sqfree(n): return all(e == 1 for e in factorint(n).values())
def fund(D):
    if D % 4 == 1: return sqfree(-D)
    if D % 4 == 0 and (D//4) % 4 in (2, 3): return sqfree(-(D//4))
    return False
L = [-D for D in range(-3, -3000, -1) if fund(D) and h(D) == 1]
assert L == [3, 4, 7, 8, 11, 19, 43, 67, 163]

